function reductionOperations(nums) {
  nums.sort((a, b) => a - b);
  let operations = 0;
  let level = 0;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] !== nums[i - 1]) {
      level++;
    }
    operations += level;
  }
  return operations;
}

