function reductionOperations(nums) {
  // Performs the operation literally until every value is the same.
  const values = nums.slice();
  let count = 0;
  for (;;) {
    const largest = Math.max(...values);
    const smaller = values.filter(v => v < largest);
    if (smaller.length === 0) return count;
    const nextLargest = Math.max(...smaller);
    values[values.indexOf(largest)] = nextLargest;
    count++;
  }
}

